import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    first_line = data[0].split()
    if not first_line:
        return
    N = int(first_line[0])
    B = int(first_line[1]) if len(first_line) > 1 else 0
    out_lines = []
    for i in range(1, 1 + B):
        if i >= len(data):
            break
        line = data[i]
        tokens = line.split()
        if len(tokens) != N:
            # pad or truncate to N tokens to be safe
            if len(tokens) < N:
                tokens += ['a'] * (N - len(tokens))
            else:
                tokens = tokens[:N]
        has_spoilt = any(tok.lower() == 'x' for tok in tokens)
        new_tokens = ['X'] * N if has_spoilt else ['A'] * N
        out_lines.append(' '.join(new_tokens))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    main()
